import { Heading, VStack } from "@chakra-ui/react";
import type { ReactNode } from "react";

interface InfoFieldProps {
  readonly label: string;
  readonly children: ReactNode;
  readonly "data-testid"?: string;
}

export function InfoField({ label, children, "data-testid": testId }: Readonly<InfoFieldProps>) {
  return (
    <VStack align="stretch" gap="1" py="2" data-testid={testId}>
      <Heading textStyle="sm">{label}</Heading>
      {children}
    </VStack>
  );
}
